package ua.budivelnyk.ua;
import android.app.Activity;import android.content.Intent;import android.content.ClipData;import android.net.Uri;import android.os.Bundle;import android.os.Environment;import android.util.Base64;import android.webkit.JavascriptInterface;import android.webkit.ValueCallback;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import org.json.JSONArray;import org.json.JSONObject;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Arrays;
public class MainActivity extends Activity{private static final int PICK=1401;private ValueCallback<Uri[]> callback;private File folder(String c){File root=getExternalFilesDir(Environment.DIRECTORY_PICTURES);if(root==null)root=getFilesDir();File d=new File(root,"drawings".equals(c)?"Креслення":"Фото_виробів");if(!d.exists())d.mkdirs();return d;}public class AndroidStorage{@JavascriptInterface public String saveImage(String c,String name,String data,String title,String notes,String date){try{int comma=data.indexOf(',');byte[] bytes=Base64.decode(comma>=0?data.substring(comma+1):data,Base64.DEFAULT);String safe=name.replaceAll("[^a-zA-Z0-9а-яА-ЯіІїЇєЄ._-]","_");File d=folder(c),f=new File(d,safe);try(FileOutputStream o=new FileOutputStream(f)){o.write(bytes);}JSONObject m=new JSONObject();m.put("title",title);m.put("notes",notes);m.put("date",date);m.put("fileName",safe);try(FileOutputStream o=new FileOutputStream(new File(d,safe+".json"))){o.write(m.toString().getBytes(StandardCharsets.UTF_8));}return "OK";}catch(Exception e){return "Помилка збереження: "+e.getMessage();}}@JavascriptInterface public String listImages(String c){JSONArray a=new JSONArray();File[] fs=folder(c).listFiles((d,n)->n.toLowerCase().endsWith(".jpg"));if(fs==null)return a.toString();Arrays.sort(fs,(x,y)->Long.compare(y.lastModified(),x.lastModified()));for(File f:fs)try{File mf=new File(f.getParentFile(),f.getName()+".json");JSONObject o=mf.exists()?new JSONObject(read(mf)):new JSONObject();o.put("fileName",f.getName());o.put("dataUrl","data:image/jpeg;base64,"+Base64.encodeToString(bytes(f),Base64.NO_WRAP));a.put(o);}catch(Exception ignored){}return a.toString();}@JavascriptInterface public String deleteImage(String c,String n){try{String s=n.replaceAll("[^a-zA-Z0-9а-яА-ЯіІїЇєЄ._-]","_");File d=folder(c),f=new File(d,s),m=new File(d,s+".json");if(f.exists()&&!f.delete())return "Не вдалося видалити";if(m.exists())m.delete();return "OK";}catch(Exception e){return "Помилка: "+e.getMessage();}}}private static byte[] bytes(File f)throws Exception{try(FileInputStream i=new FileInputStream(f);ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=i.read(b))>0)o.write(b,0,n);return o.toByteArray();}}private static String read(File f)throws Exception{return new String(bytes(f),StandardCharsets.UTF_8);}@Override public void onCreate(Bundle b){super.onCreate(b);WebView w=new WebView(this);w.setWebViewClient(new WebViewClient());w.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(callback!=null)callback.onReceiveValue(null);callback=cb;try{startActivityForResult(p.createIntent(),PICK);}catch(Exception e){callback=null;cb.onReceiveValue(null);return false;}return true;}});WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);w.addJavascriptInterface(new AndroidStorage(),"AndroidStorage");w.setBackgroundColor(0xFFF4F6F8);setContentView(w);folder("drawings");folder("products");w.loadUrl("file:///android_asset/index.html");}@Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==PICK&&callback!=null){Uri[] u=null;if(c==RESULT_OK&&d!=null){if(d.getClipData()!=null){ClipData clip=d.getClipData();u=new Uri[clip.getItemCount()];for(int i=0;i<clip.getItemCount();i++)u[i]=clip.getItemAt(i).getUri();}else if(d.getData()!=null){u=new Uri[]{d.getData()};}}callback.onReceiveValue(u);callback=null;}}}
